package admin

import _ "embed"

//go:embed permissions.js
var permissionsJS string

const permissionTemplate = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Client permissions</title><style>` + adminCSS + ` h1{overflow-wrap:anywhere}main,form{min-width:0}select{max-width:100%}table{width:100%;min-width:640px;border-collapse:collapse;font-size:14px}td,th{padding:.6rem;text-align:left;overflow-wrap:anywhere}code{overflow-wrap:anywhere}.table-wrap{overflow:auto;max-width:100%}</style><script src="{{.Base}}/admin/permissions.js" defer></script></head><body><main><nav><a href="{{.Base}}/admin/connection">Connection</a></nav><h1>Permissions · {{.Principal}}</h1><p>Global server and tool switches remain the upper limit. Newly discovered tools are never added to this ACL automatically.</p><p>Audit: <strong data-audit-status>{{.Audit}}</strong>{{if eq .Audit "degraded"}} · Saved operations remain committed; audit delivery is unavailable.{{end}}</p>{{if .Legacy}}<p class="warning" data-legacy-warning>Legacy shared access: this principal can use globally enabled shared tools. Choose restricted and explicitly select its tools to narrow access.</p>{{end}}<p data-permission-status role="status">{{.Message}}</p><form method="post" data-permissions><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="revision" value="{{.Revision}}"><label>Access policy<select name="policy">{{if .Legacy}}<option value="legacy_shared" {{if eq .Policy "legacy_shared"}}selected{{end}}>Legacy shared (existing access)</option>{{end}}<option value="restricted" {{if eq .Policy "restricted"}}selected{{end}}>Restricted — exact selected tools only</option></select></label><div class="table-wrap"><table><thead><tr><th>Configured permission</th><th>Global availability</th><th>Current policy</th><th>Inherited argument constraints</th></tr></thead><tbody>{{range .Rows}}<tr><td><label><input type="checkbox" name="{{.Field}}" value="1" {{if .Selected}}checked{{end}}> {{.Server}} / {{.Tool}}</label></td><td>{{if .Enabled}}Enabled{{else}}Disabled{{end}}</td><td data-policy-cell>{{if .Allowed}}Allowed{{else}}Denied{{end}}</td><td><code>{{.Constraints}}</code></td></tr>{{end}}</tbody></table></div><p>No selected tools means no access in restricted mode. Saving is explicit and does not invoke upstream tools.</p><button type="submit" {{if .Uncertain}}disabled{{end}}>Save permissions</button></form><p>Registry revision <span data-permission-revision>{{.Revision}}</span></p><a href="{{.Base}}/admin/connection/permissions/{{.Principal}}">Reload saved permissions (discards draft)</a><noscript><p>Forms work without JavaScript. If a save cannot be confirmed, reload saved permissions before retrying.</p></noscript></main></body></html>`
